"""Order fulfillment: SQLite-backed order service with inventory reservation.

Standard library only. No network, subprocess, eval, or exec.
"""

from __future__ import annotations

import json
import math
import sqlite3
from typing import Any, Dict, List, Optional


class OrderError(Exception):
    """Stable order-domain error.

    Attributes:
        code: stable machine-readable code.
        message: human-readable message (also returned by str()).
        details: arbitrary structured context.
    """

    def __init__(self, code: str, message: str, details: Optional[dict] = None):
        super().__init__(message)
        self.code = code
        self.message = message
        self.details: dict = details if details is not None else {}

    def __str__(self) -> str:
        return self.message


# Status constants
PENDING = "pending"
PAID = "paid"
SHIPPED = "shipped"
CANCELLED = "cancelled"
_VALID_STATUSES = (PENDING, PAID, SHIPPED, CANCELLED)

# Code constants
CODE_INVALID_INPUT = "INVALID_INPUT"
CODE_INVALID_DEPENDENCY = "INVALID_DEPENDENCY"
CODE_NOT_FOUND = "NOT_FOUND"
CODE_INSUFFICIENT_STOCK = "INSUFFICIENT_STOCK"
CODE_IDEMPOTENCY_CONFLICT = "IDEMPOTENCY_CONFLICT"
CODE_PAYMENT_CONFLICT = "PAYMENT_CONFLICT"
CODE_AMOUNT_MISMATCH = "AMOUNT_MISMATCH"
CODE_INVALID_STATE = "INVALID_STATE"
CODE_ID_COLLISION = "ID_COLLISION"
CODE_SCHEMA_MISMATCH = "SCHEMA_MISMATCH"
CODE_STORAGE_ERROR = "STORAGE_ERROR"


def _is_nonempty_str(value: Any) -> bool:
    return isinstance(value, str) and value != "" and not value.isspace()


def _is_int(value: Any) -> bool:
    # bool is a subclass of int and must be rejected.
    return isinstance(value, int) and not isinstance(value, bool)


def _is_finite_number(value: Any) -> bool:
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)):
        return math.isfinite(value)
    return False


def _require_nonempty_str(value: Any, field: str) -> str:
    if not _is_nonempty_str(value):
        raise OrderError(
            CODE_INVALID_INPUT,
            f"{field} must be a non-empty string",
            {"field": field},
        )
    return value


def _require_int_ge(value: Any, field: str, minimum: int) -> int:
    if not _is_int(value) or value < minimum:
        raise OrderError(
            CODE_INVALID_INPUT,
            f"{field} must be an integer >= {minimum}",
            {"field": field, "value": value},
        )
    return value


def _require_int_gt(value: Any, field: str, minimum: int) -> int:
    if not _is_int(value) or value <= minimum:
        raise OrderError(
            CODE_INVALID_INPUT,
            f"{field} must be an integer > {minimum}",
            {"field": field, "value": value},
        )
    return value


def _check_dependency(value: Any, what: str) -> Any:
    if not _is_finite_number(value):
        raise OrderError(
            CODE_INVALID_DEPENDENCY,
            f"{what} returned an invalid (non-finite) value",
            {"value": value},
        )
    return value


class OrderService:
    """SQLite-backed order service with inventory reservation."""

    SCHEMA_VERSION = 1

    def __init__(self, db_path, *, clock, id_factory):
        self._db_path = db_path
        self._clock = clock
        self._id_factory = id_factory
        try:
            self._conn = sqlite3.connect(db_path, isolation_level=None)
            self._conn.execute("PRAGMA journal_mode=WAL")
            self._conn.execute("PRAGMA foreign_keys=ON")
        except sqlite3.Error as exc:
            raise OrderError(
                CODE_STORAGE_ERROR,
                "failed to open database",
                {"error": str(exc)},
            ) from exc
        try:
            self._init_schema()
        except OrderError:
            self._conn.close()
            raise

    # ---- schema -------------------------------------------------------------
    def _init_schema(self) -> None:
        cur = self._conn.cursor()
        # Verify an existing file has a compatible schema.
        existing = self._list_tables(cur)
        if existing:
            self._validate_schema(cur)
            return
        cur.execute(
            """
            CREATE TABLE stock (
                sku TEXT PRIMARY KEY NOT NULL,
                total INTEGER NOT NULL,
                reserved INTEGER NOT NULL DEFAULT 0,
                CHECK (total >= 0 AND reserved >= 0 AND reserved <= total)
            )
            """
        )
        cur.execute(
            """
            CREATE TABLE orders (
                order_id TEXT PRIMARY KEY NOT NULL,
                idempotency_key TEXT NOT NULL UNIQUE,
                status TEXT NOT NULL,
                total_cents INTEGER NOT NULL,
                payment_id TEXT,
                created_at REAL NOT NULL,
                updated_at REAL NOT NULL,
                CHECK (status IN ('pending','paid','shipped','cancelled')),
                CHECK (total_cents >= 0)
            )
            """
        )
        cur.execute(
            """
            CREATE TABLE order_items (
                order_id TEXT NOT NULL,
                sku TEXT NOT NULL,
                quantity INTEGER NOT NULL,
                unit_price_cents INTEGER NOT NULL,
                PRIMARY KEY (order_id, sku),
                CHECK (quantity > 0),
                CHECK (unit_price_cents >= 0),
                FOREIGN KEY (order_id) REFERENCES orders(order_id)
            )
            """
        )
        cur.execute(
            "CREATE TABLE meta (key TEXT PRIMARY KEY NOT NULL, value INTEGER NOT NULL)"
        )
        cur.execute(
            "INSERT INTO meta(key, value) VALUES ('schema_version', ?)",
            (self.SCHEMA_VERSION,),
        )

    @staticmethod
    def _list_tables(cur) -> List[str]:
        cur.execute("SELECT name FROM sqlite_master WHERE type='table'")
        return [row[0] for row in cur.fetchall()]

    def _validate_schema(self, cur) -> None:
        expected = {
            "stock": {"sku", "total", "reserved"},
            "orders": {
                "order_id",
                "idempotency_key",
                "status",
                "total_cents",
                "payment_id",
                "created_at",
                "updated_at",
            },
            "order_items": {"order_id", "sku", "quantity", "unit_price_cents"},
        }
        for table, cols in expected.items():
            cur.execute(f"PRAGMA table_info({table})")
            got = {row[1] for row in cur.fetchall()}
            if got != cols:
                raise OrderError(
                    CODE_SCHEMA_MISMATCH,
                    f"incompatible schema for table {table}",
                    {"table": table, "expected": sorted(cols), "found": sorted(got)},
                )
        cur.execute("SELECT value FROM meta WHERE key='schema_version'")
        row = cur.fetchone()
        if row is None or row[0] != self.SCHEMA_VERSION:
            raise OrderError(
                CODE_SCHEMA_MISMATCH,
                "unsupported schema_version",
                {"found": None if row is None else row[0]},
            )

    def close(self) -> None:
        try:
            self._conn.close()
        except sqlite3.Error:
            pass

    # ---- helpers ------------------------------------------------------------
    def _gen_order_id(self) -> str:
        attempts = 0
        while attempts < 3:
            raw = self._id_factory()
            if not _is_nonempty_str(raw):
                raise OrderError(
                    CODE_INVALID_DEPENDENCY,
                    "id_factory returned invalid id",
                    {"value": raw},
                )
            attempts += 1
            cur = self._conn.execute(
                "SELECT 1 FROM orders WHERE order_id = ?", (raw,)
            )
            if cur.fetchone() is None:
                return raw
        raise OrderError(
            CODE_ID_COLLISION,
            "could not generate a unique order id after retries",
            {"attempts": attempts},
        )

    def _now(self) -> float:
        return float(_check_dependency(self._clock(), "clock"))

    @staticmethod
    def _canonical_items(items: List[Dict[str, Any]]) -> List[tuple]:
        return sorted(
            (it["sku"], int(it["quantity"]), int(it["unit_price_cents"]))
            for it in items
        )

    def _row_to_order(self, row: tuple, items: List[Dict[str, Any]]) -> dict:
        return {
            "order_id": row[0],
            "idempotency_key": row[1],
            "status": row[2],
            "items": [
                {
                    "sku": it["sku"],
                    "quantity": it["quantity"],
                    "unit_price_cents": it["unit_price_cents"],
                }
                for it in sorted(items, key=lambda x: x["sku"])
            ],
            "total_cents": row[3],
            "payment_id": row[4],
            "created_at": row[5],
            "updated_at": row[6],
        }

    def _load_order(self, order_id: str) -> Optional[dict]:
        cur = self._conn.execute(
            "SELECT order_id, idempotency_key, status, total_cents, payment_id, "
            "created_at, updated_at FROM orders WHERE order_id = ?",
            (order_id,),
        )
        row = cur.fetchone()
        if row is None:
            return None
        items = self._load_items(order_id)
        return self._row_to_order(row, items)

    def _load_items(self, order_id: str) -> List[Dict[str, Any]]:
        cur = self._conn.execute(
            "SELECT sku, quantity, unit_price_cents FROM order_items WHERE order_id = ?",
            (order_id,),
        )
        return [
            {"sku": r[0], "quantity": r[1], "unit_price_cents": r[2]}
            for r in cur.fetchall()
        ]

    # ---- public API ---------------------------------------------------------
    def set_stock(self, sku: str, quantity: int) -> dict:
        _require_nonempty_str(sku, "sku")
        qty = _require_int_ge(quantity, "quantity", 0)
        try:
            self._conn.execute("BEGIN IMMEDIATE")
            self._conn.execute(
                "INSERT INTO stock(sku, total, reserved) VALUES(?, ?, 0) "
                "ON CONFLICT(sku) DO UPDATE SET total = excluded.total",
                (sku, qty),
            )
            self._conn.execute("COMMIT")
        except sqlite3.Error as exc:
            self._safe_rollback()
            raise OrderError(
                CODE_STORAGE_ERROR, "failed to set stock", {"error": str(exc)}
            ) from exc
        available = self._available(sku)
        return {"sku": sku, "available": available}

    def _available(self, sku: str) -> int:
        cur = self._conn.execute(
            "SELECT total - reserved FROM stock WHERE sku = ?", (sku,)
        )
        row = cur.fetchone()
        return row[0] if row is not None else 0

    def create_order(self, idempotency_key: str, items: list) -> dict:
        _require_nonempty_str(idempotency_key, "idempotency_key")
        if not isinstance(items, list) or len(items) == 0:
            raise OrderError(
                CODE_INVALID_INPUT,
                "items must be a non-empty list",
                {"value": items},
            )
        # Validate and canonicalize items.
        seen = set()
        validated = []
        for idx, it in enumerate(items):
            if not isinstance(it, dict):
                raise OrderError(
                    CODE_INVALID_INPUT,
                    f"item[{idx}] must be an object",
                    {"index": idx},
                )
            allowed = {"sku", "quantity", "unit_price_cents"}
            extra = set(it.keys()) - allowed
            if extra:
                raise OrderError(
                    CODE_INVALID_INPUT,
                    f"item[{idx}] has unknown fields",
                    {"index": idx, "fields": sorted(extra)},
                )
            sku = _require_nonempty_str(it.get("sku"), f"items[{idx}].sku")
            quantity = _require_int_gt(it.get("quantity"), f"items[{idx}].quantity", 0)
            unit_price = _require_int_ge(
                it.get("unit_price_cents"), f"items[{idx}].unit_price_cents", 0
            )
            if sku in seen:
                raise OrderError(
                    CODE_INVALID_INPUT,
                    f"duplicate sku in items: {sku}",
                    {"sku": sku},
                )
            seen.add(sku)
            validated.append(
                {
                    "sku": sku,
                    "quantity": quantity,
                    "unit_price_cents": unit_price,
                }
            )
        canonical = self._canonical_items(validated)
        total_cents = sum(v["quantity"] * v["unit_price_cents"] for v in validated)

        try:
            self._conn.execute("BEGIN IMMEDIATE")
            # Idempotency: same key already exists?
            cur = self._conn.execute(
                "SELECT order_id, status, total_cents FROM orders WHERE idempotency_key = ?",
                (idempotency_key,),
            )
            existing = cur.fetchone()
            if existing is not None:
                order_id = existing[0]
                items_cur = self._conn.execute(
                    "SELECT sku, quantity, unit_price_cents FROM order_items WHERE order_id = ?",
                    (order_id,),
                )
                existing_items = sorted(
                    (r[0], r[1], r[2]) for r in items_cur.fetchall()
                )
                if existing_items == canonical and existing[2] == total_cents:
                    self._conn.execute("COMMIT")
                    return self._load_order(order_id)
                raise OrderError(
                    CODE_IDEMPOTENCY_CONFLICT,
                    "idempotency_key reused with different items",
                    {"idempotency_key": idempotency_key},
                )

            # Stock check across all SKUs (no partial decrement on failure).
            for (sku, qty, _) in canonical:
                cur = self._conn.execute(
                    "SELECT total - reserved FROM stock WHERE sku = ?", (sku,)
                )
                row = cur.fetchone()
                avail = row[0] if row is not None else 0
                if avail < qty:
                    raise OrderError(
                        CODE_INSUFFICIENT_STOCK,
                        f"insufficient stock for sku {sku}",
                        {"sku": sku, "available": avail, "requested": qty},
                    )

            order_id = self._gen_order_id()
            now = self._now()
            self._conn.execute(
                "INSERT INTO orders(order_id, idempotency_key, status, total_cents, "
                "payment_id, created_at, updated_at) VALUES(?, ?, 'pending', ?, NULL, ?, ?)",
                (order_id, idempotency_key, total_cents, now, now),
            )
            for (sku, qty, unit_price) in canonical:
                self._conn.execute(
                    "INSERT INTO order_items(order_id, sku, quantity, unit_price_cents) "
                    "VALUES(?, ?, ?, ?)",
                    (order_id, sku, qty, unit_price),
                )
                self._conn.execute(
                    "UPDATE stock SET reserved = reserved + ? WHERE sku = ?",
                    (qty, sku),
                )
            self._conn.execute("COMMIT")
        except OrderError:
            self._safe_rollback()
            raise
        except sqlite3.Error as exc:
            self._safe_rollback()
            raise OrderError(
                CODE_STORAGE_ERROR, "failed to create order", {"error": str(exc)}
            ) from exc
        return self._load_order(order_id)

    def pay_order(self, order_id: str, payment_id: str, amount_cents: int) -> dict:
        _require_nonempty_str(order_id, "order_id")
        _require_nonempty_str(payment_id, "payment_id")
        amount = _require_int_ge(amount_cents, "amount_cents", 0)
        try:
            self._conn.execute("BEGIN IMMEDIATE")
            cur = self._conn.execute(
                "SELECT order_id, status, total_cents, payment_id FROM orders WHERE order_id = ?",
                (order_id,),
            )
            row = cur.fetchone()
            if row is None:
                raise OrderError(
                    CODE_NOT_FOUND, "order not found", {"order_id": order_id}
                )
            status = row[1]
            total_cents = row[2]
            existing_payment = row[3]

            # Idempotent repeat of the exact same payment.
            if existing_payment is not None:
                cur = self._conn.execute(
                    "SELECT amount_cents FROM payments WHERE order_id = ? AND payment_id = ?",
                    (order_id, payment_id),
                )
                prow = cur.fetchone()
                if prow is not None and prow[0] == amount:
                    self._conn.execute("COMMIT")
                    return self._load_order(order_id)

            if amount != total_cents:
                raise OrderError(
                    CODE_AMOUNT_MISMATCH,
                    "amount_cents does not match order total",
                    {"amount": amount, "total": total_cents},
                )

            if status != PENDING:
                raise OrderError(
                    CODE_INVALID_STATE,
                    f"cannot pay order in status {status}",
                    {"status": status},
                )

            # Payment id conflict checks.
            cur = self._conn.execute(
                "SELECT order_id, amount_cents FROM payments WHERE payment_id = ?",
                (payment_id,),
            )
            for prow in cur.fetchall():
                if prow[0] != order_id or prow[1] != amount:
                    raise OrderError(
                        CODE_PAYMENT_CONFLICT,
                        "payment_id reused for a different order or amount",
                        {"payment_id": payment_id},
                    )
            if existing_payment is not None and existing_payment != payment_id:
                raise OrderError(
                    CODE_PAYMENT_CONFLICT,
                    "order already paid with a different payment_id",
                    {"order_id": order_id, "payment_id": payment_id},
                )

            now = self._now()
            self._conn.execute(
                "UPDATE orders SET status='paid', payment_id=?, updated_at=? WHERE order_id=?",
                (payment_id, now, order_id),
            )
            self._conn.execute(
                "INSERT INTO payments(order_id, payment_id, amount_cents) VALUES(?, ?, ?)",
                (order_id, payment_id, amount),
            )
            self._conn.execute("COMMIT")
        except OrderError:
            self._safe_rollback()
            raise
        except sqlite3.Error as exc:
            self._safe_rollback()
            raise OrderError(
                CODE_STORAGE_ERROR, "failed to pay order", {"error": str(exc)}
            ) from exc
        return self._load_order(order_id)

    def cancel_order(self, order_id: str) -> dict:
        _require_nonempty_str(order_id, "order_id")
        try:
            self._conn.execute("BEGIN IMMEDIATE")
            cur = self._conn.execute(
                "SELECT order_id, status FROM orders WHERE order_id = ?", (order_id,)
            )
            row = cur.fetchone()
            if row is None:
                raise OrderError(
                    CODE_NOT_FOUND, "order not found", {"order_id": order_id}
                )
            status = row[1]
            if status == CANCELLED:
                self._conn.execute("COMMIT")
                return self._load_order(order_id)
            if status == SHIPPED:
                raise OrderError(
                    CODE_INVALID_STATE,
                    "cannot cancel a shipped order",
                    {"order_id": order_id},
                )
            self._release_reservation(order_id)
            now = self._now()
            self._conn.execute(
                "UPDATE orders SET status='cancelled', updated_at=? WHERE order_id=?",
                (now, order_id),
            )
            self._conn.execute("COMMIT")
        except OrderError:
            self._safe_rollback()
            raise
        except sqlite3.Error as exc:
            self._safe_rollback()
            raise OrderError(
                CODE_STORAGE_ERROR, "failed to cancel order", {"error": str(exc)}
            ) from exc
        return self._load_order(order_id)

    def ship_order(self, order_id: str) -> dict:
        _require_nonempty_str(order_id, "order_id")
        try:
            self._conn.execute("BEGIN IMMEDIATE")
            cur = self._conn.execute(
                "SELECT order_id, status FROM orders WHERE order_id = ?", (order_id,)
            )
            row = cur.fetchone()
            if row is None:
                raise OrderError(
                    CODE_NOT_FOUND, "order not found", {"order_id": order_id}
                )
            status = row[1]
            if status == SHIPPED:
                self._conn.execute("COMMIT")
                return self._load_order(order_id)
            if status != PAID:
                raise OrderError(
                    CODE_INVALID_STATE,
                    f"cannot ship order in status {status}",
                    {"status": status},
                )
            # Consume reserved stock: convert reservation into actual consumption.
            self._conn.execute(
                "UPDATE stock SET total = total - quantity_from_items.reserved, "
                "reserved = reserved - quantity_from_items.reserved "
                "WHERE sku IN (SELECT sku FROM order_items WHERE order_id = ?) "
                "AND 0",
                (order_id,),
            )
            # Per-sku decrement (must be exact; use a clear loop).
            cur = self._conn.execute(
                "SELECT sku, quantity FROM order_items WHERE order_id = ?", (order_id,)
            )
            for sku, qty in cur.fetchall():
                self._conn.execute(
                    "UPDATE stock SET total = total - ?, reserved = reserved - ? "
                    "WHERE sku = ?",
                    (qty, qty, sku),
                )
            now = self._now()
            self._conn.execute(
                "UPDATE orders SET status='shipped', updated_at=? WHERE order_id=?",
                (now, order_id),
            )
            self._conn.execute("COMMIT")
        except OrderError:
            self._safe_rollback()
            raise
        except sqlite3.Error as exc:
            self._safe_rollback()
            raise OrderError(
                CODE_STORAGE_ERROR, "failed to ship order", {"error": str(exc)}
            ) from exc
        return self._load_order(order_id)

    def _release_reservation(self, order_id: str) -> None:
        cur = self._conn.execute(
            "SELECT sku, quantity FROM order_items WHERE order_id = ?", (order_id,)
        )
        for sku, qty in cur.fetchall():
            self._conn.execute(
                "UPDATE stock SET reserved = reserved - ? WHERE sku = ?",
                (qty, sku),
            )

    def get_order(self, order_id: str) -> dict:
        _require_nonempty_str(order_id, "order_id")
        order = self._load_order(order_id)
        if order is None:
            raise OrderError(
                CODE_NOT_FOUND, "order not found", {"order_id": order_id}
            )
        return order

    def _safe_rollback(self) -> None:
        try:
            self._conn.execute("ROLLBACK")
        except sqlite3.Error:
            pass


__all__ = ["OrderError", "OrderService"]

