"""Delivery spool: filesystem-backed durable message lease queue.

Standard library only. No network, subprocess, eval, or exec.

Durable commit protocol: each mutation acquires an exclusive interprocess lock,
re-reads and validates state while locked, writes a same-directory temp file,
flushes and fsyncs it, atomically os.replaces state.json, and fsyncs the root
directory where supported, then removes temp files and releases the lock in a
`finally`. Lock acquisition prevents concurrent lost updates / double claims.
"""

from __future__ import annotations

import dataclasses
import json
import math
import os
import secrets
import sys
import time
import tempfile
from typing import Any, Dict, List, Optional

# ---------------------------------------------------------------------------
# Limits
# ---------------------------------------------------------------------------
@dataclasses.dataclass(frozen=True)
class Limits:
    max_messages: int = 10000
    max_payload_bytes: int = 65536
    max_attempts: int = 5
    lease_seconds: float = 30.0
    retry_delay: float = 10.0


# ---------------------------------------------------------------------------
# Error
# ---------------------------------------------------------------------------
class SpoolError(Exception):
    """Stable spool-domain error."""

    def __init__(self, code: str, message: str, details: Optional[dict] = None):
        super().__init__(message)
        self.code = code
        self.message = message
        self.details: dict = details if details is not None else {}

    def __str__(self) -> str:
        return self.message


# ---------------------------------------------------------------------------
# Codes
# ---------------------------------------------------------------------------
CODE_INVALID_INPUT = "INVALID_INPUT"
CODE_INVALID_DEPENDENCY = "INVALID_DEPENDENCY"
CODE_NOT_INITIALIZED = "NOT_INITIALIZED"
CODE_ALREADY_INITIALIZED = "ALREADY_INITIALIZED"
CODE_NOT_FOUND = "NOT_FOUND"
CODE_IDEMPOTENCY_CONFLICT = "IDEMPOTENCY_CONFLICT"
CODE_CAPACITY_EXCEEDED = "CAPACITY_EXCEEDED"
CODE_UNAUTHORIZED = "UNAUTHORIZED"
CODE_INVALID_STATE = "INVALID_STATE"
CODE_CORRUPT_STATE = "CORRUPT_STATE"
CODE_SCHEMA_MISMATCH = "SCHEMA_MISMATCH"
CODE_LOCK_TIMEOUT = "LOCK_TIMEOUT"
CODE_INTERNAL_ERROR = "INTERNAL_ERROR"

SCHEMA_VERSION = 1
STATE_FILENAME = "state.json"
LOCK_FILENAME = "state.lock"

VALID_STATUSES = ("pending", "leased", "acked", "dead")
MESSAGE_PUBLIC_FIELDS = {
    "message_id",
    "payload",
    "status",
    "available_at",
    "sequence",
    "attempts",
    "last_error",
}


# ---------------------------------------------------------------------------
# Validation helpers
# ---------------------------------------------------------------------------
def _is_nonempty_str(value: Any) -> bool:
    return isinstance(value, str) and value != "" and not value.isspace()


def _is_int(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _is_finite_number(value: Any) -> bool:
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)):
        return math.isfinite(value)
    return False


def _validate_limits(limits: Limits) -> None:
    if not isinstance(limits, Limits):
        raise SpoolError(
            CODE_INVALID_INPUT, "limits must be a Limits instance", {}
        )
    if isinstance(limits.max_messages, bool) or not _is_int(limits.max_messages) or limits.max_messages <= 0:
        raise SpoolError(CODE_INVALID_INPUT, "max_messages must be a positive integer", {})
    if isinstance(limits.max_payload_bytes, bool) or not _is_int(limits.max_payload_bytes) or limits.max_payload_bytes <= 0:
        raise SpoolError(CODE_INVALID_INPUT, "max_payload_bytes must be a positive integer", {})
    if isinstance(limits.max_attempts, bool) or not _is_int(limits.max_attempts) or limits.max_attempts <= 0:
        raise SpoolError(CODE_INVALID_INPUT, "max_attempts must be a positive integer", {})
    if isinstance(limits.lease_seconds, bool) or not _is_finite_number(limits.lease_seconds) or limits.lease_seconds <= 0:
        raise SpoolError(CODE_INVALID_INPUT, "lease_seconds must be a finite number > 0", {})
    if isinstance(limits.retry_delay, bool) or not _is_finite_number(limits.retry_delay) or limits.retry_delay < 0:
        raise SpoolError(CODE_INVALID_INPUT, "retry_delay must be a finite number >= 0", {})


def _validate_lock_timeout(lock_timeout: float) -> None:
    if isinstance(lock_timeout, bool) or not _is_finite_number(lock_timeout) or lock_timeout < 0:
        raise SpoolError(
            CODE_INVALID_INPUT, "lock_timeout must be a finite number >= 0", {}
        )


def _require_nonempty_str(value: Any, field: str) -> str:
    if not _is_nonempty_str(value):
        raise SpoolError(CODE_INVALID_INPUT, f"{field} must be a non-empty string", {"field": field})
    return value


def _payload_canonical(payload: Any) -> bytes:
    """Return canonical UTF-8 bytes for a payload, validating JSON-ability."""
    try:
        text = json.dumps(payload, ensure_ascii=False, allow_nan=False, sort_keys=True, separators=(",", ":"))
    except (TypeError, ValueError) as exc:
        raise SpoolError(
            CODE_INVALID_INPUT, "payload is not JSON-serializable", {"error": str(exc)}
        ) from exc
    return text.encode("utf-8")


def _canonical_obj(value: Any) -> Any:
    """Detach caller mutations by round-tripping through JSON."""
    text = json.dumps(value, ensure_ascii=False, allow_nan=False, sort_keys=True, separators=(",", ":"))
    return json.loads(text)


# ---------------------------------------------------------------------------
# State validation
# ---------------------------------------------------------------------------
def _validate_state(state: Any, top_level_only: bool = False) -> dict:
    """Validate a parsed state object. Raises SpoolError on any corruption."""
    if not isinstance(state, dict):
        raise SpoolError(CODE_CORRUPT_STATE, "state root is not an object", {})
    if "schema_version" not in state:
        raise SpoolError(CODE_CORRUPT_STATE, "missing schema_version", {})
    if state["schema_version"] != SCHEMA_VERSION:
        raise SpoolError(
            CODE_SCHEMA_MISMATCH, "unknown schema_version", {"found": state["schema_version"]}
        )
    if "next_sequence" not in state:
        raise SpoolError(CODE_CORRUPT_STATE, "missing next_sequence", {})
    if not _is_int(state["next_sequence"]) or state["next_sequence"] < 1:
        raise SpoolError(CODE_CORRUPT_STATE, "invalid next_sequence", {})
    if "messages" not in state:
        raise SpoolError(CODE_CORRUPT_STATE, "missing messages", {})
    if not isinstance(state["messages"], dict):
        raise SpoolError(CODE_CORRUPT_STATE, "messages is not an object", {})

    allowed_top = {"schema_version", "next_sequence", "messages"}
    extra = set(state.keys()) - allowed_top
    if extra:
        raise SpoolError(CODE_CORRUPT_STATE, "unknown top-level fields", {"fields": sorted(extra)})

    if top_level_only:
        return state

    for mid, msg in state["messages"].items():
        if not isinstance(msg, dict):
            raise SpoolError(CODE_CORRUPT_STATE, f"message {mid} is not an object", {})
        _validate_message(mid, msg)
    return state


def _validate_message(mid: str, msg: dict) -> None:
    allowed = {
        "message_id",
        "payload",
        "status",
        "available_at",
        "sequence",
        "attempts",
        "last_error",
        "worker_id",
        "lease_token",
        "expires_at",
    }
    extra = set(msg.keys()) - allowed
    if extra:
        raise SpoolError(
            CODE_CORRUPT_STATE, f"message {mid} has unknown fields", {"fields": sorted(extra)}
        )
    if msg.get("message_id") != mid:
        raise SpoolError(CODE_CORRUPT_STATE, f"message_id mismatch for {mid}", {})
    if msg.get("status") not in VALID_STATUSES:
        raise SpoolError(CODE_CORRUPT_STATE, f"message {mid} has invalid status", {})
    if not _is_finite_number(msg.get("available_at")):
        raise SpoolError(CODE_CORRUPT_STATE, f"message {mid} has invalid available_at", {})
    if not _is_int(msg.get("sequence")) or msg.get("sequence") < 1:
        raise SpoolError(CODE_CORRUPT_STATE, f"message {mid} has invalid sequence", {})
    if not _is_int(msg.get("attempts")) or msg.get("attempts") < 0:
        raise SpoolError(CODE_CORRUPT_STATE, f"message {mid} has invalid attempts", {})
    if msg.get("last_error") is not None and not isinstance(msg.get("last_error"), str):
        raise SpoolError(CODE_CORRUPT_STATE, f"message {mid} has invalid last_error", {})
    # Consistency: leased must have token/expires_at; non-leased must not.
    if msg.get("status") == "leased":
        if not _is_nonempty_str(msg.get("lease_token")):
            raise SpoolError(CODE_CORRUPT_STATE, f"message {mid} leased without lease_token", {})
        if not _is_finite_number(msg.get("expires_at")):
            raise SpoolError(CODE_CORRUPT_STATE, f"message {mid} leased without expires_at", {})
        if not _is_nonempty_str(msg.get("worker_id")):
            raise SpoolError(CODE_CORRUPT_STATE, f"message {mid} leased without worker_id", {})
    else:
        if msg.get("lease_token") is not None:
            raise SpoolError(CODE_CORRUPT_STATE, f"message {mid} not leased but has lease_token", {})
        if msg.get("expires_at") is not None:
            raise SpoolError(CODE_CORRUPT_STATE, f"message {mid} not leased but has expires_at", {})
        if msg.get("worker_id") is not None:
            raise SpoolError(CODE_CORRUPT_STATE, f"message {mid} not leased but has worker_id", {})


def _message_public(msg: dict) -> dict:
    return {
        "message_id": msg["message_id"],
        "payload": _canonical_obj(msg["payload"]),
        "status": msg["status"],
        "available_at": msg["available_at"],
        "sequence": msg["sequence"],
        "attempts": msg["attempts"],
        "last_error": msg["last_error"],
    }


# ---------------------------------------------------------------------------
# Spool
# ---------------------------------------------------------------------------
class Spool:
    def __init__(self, root, *, clock, limits, lock_timeout, failpoint):
        # Constructor validation must not write.
        if not isinstance(root, str) or root == "":
            raise SpoolError(CODE_INVALID_INPUT, "root must be a non-empty string", {})
        _validate_limits(limits)
        _validate_lock_timeout(lock_timeout)
        if not callable(clock):
            raise SpoolError(CODE_INVALID_INPUT, "clock must be callable", {})
        if failpoint is not None and not callable(failpoint):
            raise SpoolError(CODE_INVALID_INPUT, "failpoint must be callable or None", {})

        self._root = root
        self._clock = clock
        self._limits = limits
        self._lock_timeout = float(lock_timeout)
        self._failpoint = failpoint

    # ---- state read ---------------------------------------------------------
    def _read_state(self) -> dict:
        path = os.path.join(self._root, STATE_FILENAME)
        try:
            with open(path, "r", encoding="utf-8") as fh:
                raw = fh.read()
        except FileNotFoundError:
            raise SpoolError(CODE_NOT_INITIALIZED, "spool not initialized", {})
        except OSError as exc:
            raise SpoolError(CODE_CORRUPT_STATE, "cannot read state", {"error": str(exc)}) from exc
        if raw == "":
            raise SpoolError(CODE_CORRUPT_STATE, "state file is empty", {})
        try:
            parsed = json.loads(raw)
        except json.JSONDecodeError as exc:
            raise SpoolError(CODE_CORRUPT_STATE, "state is not valid JSON", {"error": str(exc)}) from exc
        # Duplicate-key detection: json.loads keeps last; detect by scanning textually.
        if _has_duplicate_keys(raw):
            raise SpoolError(CODE_CORRUPT_STATE, "state contains duplicate JSON keys", {})
        return _validate_state(parsed)

    def _now(self) -> float:
        val = self._clock()
        if not _is_finite_number(val):
            raise SpoolError(CODE_INVALID_DEPENDENCY, "clock returned invalid value", {"value": val})
        return float(val)

    def _call_failpoint(self, name: str) -> None:
        if self._failpoint is not None:
            self._failpoint(name)

    # ---- lock + commit ------------------------------------------------------
    def _acquire_lock(self):
        lock_path = os.path.join(self._root, LOCK_FILENAME)
        deadline = time.monotonic() + self._lock_timeout
        while True:
            try:
                fd = os.open(lock_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o644)
                # Record owning pid for diagnostics (not required).
                with os.fdopen(fd, "w", encoding="utf-8") as fh:
                    fh.write(str(os.getpid()))
                return _LockHandle(lock_path)
            except FileExistsError:
                if time.monotonic() >= deadline:
                    raise SpoolError(
                        CODE_LOCK_TIMEOUT,
                        "could not acquire spool lock",
                        {"lock_path": lock_path},
                    )
                time.sleep(0.01)
            except OSError as exc:
                raise SpoolError(CODE_INTERNAL_ERROR, "lock acquisition failed", {"error": str(exc)}) from exc

    def _commit(self, state: dict) -> None:
        """Write state atomically: temp file + fsync + replace + dir fsync."""
        root = self._root
        text = json.dumps(
            state, ensure_ascii=False, allow_nan=False, sort_keys=True, separators=(",", ":")
        )
        text += "\n"
        data = text.encode("utf-8")
        tmp_name = f".state.{os.getpid()}.{secrets.token_hex(8)}.tmp"
        tmp_path = os.path.join(root, tmp_name)
        with open(tmp_path, "wb") as fh:
            fh.write(data)
            fh.flush()
            os.fsync(fh.fileno())
        self._call_failpoint("before_replace")
        state_path = os.path.join(root, STATE_FILENAME)
        os.replace(tmp_path, state_path)
        # fsync the directory where supported.
        self._call_failpoint("after_replace")
        self._fsync_dir(root)

    @staticmethod
    def _fsync_dir(path: str) -> None:
        if sys.platform == "win32":
            # Windows has no portable dir fsync; ignore.
            return
        try:
            dfd = os.open(path, os.O_RDONLY)
            try:
                os.fsync(dfd)
            finally:
                os.close(dfd)
        except OSError:
            pass

    def _mutate(self, fn) -> Any:
        """Acquire lock, re-read+validate state, run fn(state), commit, release."""
        lock = self._acquire_lock()
        tmp_files = []
        try:
            self._call_failpoint("after_lock")
            state = self._read_state()
            result = fn(state)
            self._commit(state)
            return result
        except SpoolError:
            raise
        except Exception as exc:  # noqa: BLE001
            raise SpoolError(CODE_INTERNAL_ERROR, "internal failure", {"error": str(exc)}) from exc
        finally:
            # Clean up any leftover temp files for this pid.
            try:
                for name in os.listdir(self._root):
                    if name.startswith(f".state.{os.getpid()}.") and name.endswith(".tmp"):
                        try:
                            os.remove(os.path.join(self._root, name))
                        except OSError:
                            pass
            except OSError:
                pass
            lock.release()

    # read-only lock (prevents observing a replacement race)
    def _read_locked(self, fn) -> Any:
        lock = self._acquire_lock()
        try:
            self._call_failpoint("after_lock")
            state = self._read_state()
            return fn(state)
        finally:
            lock.release()

    # ---- public API ---------------------------------------------------------
    def initialize(self) -> dict:
        # Create root if needed; do not fail if exists.
        try:
            os.makedirs(self._root, exist_ok=True)
        except OSError as exc:
            raise SpoolError(CODE_INTERNAL_ERROR, "cannot create root", {"error": str(exc)}) from exc
        lock = self._acquire_lock()
        try:
            self._call_failpoint("after_lock")
            state_path = os.path.join(self._root, STATE_FILENAME)
            if os.path.exists(state_path):
                # Already initialized: validate it (fail closed on corruption).
                try:
                    self._read_state()
                except SpoolError:
                    raise
                raise SpoolError(CODE_ALREADY_INITIALIZED, "spool already initialized", {})
            state = {"schema_version": SCHEMA_VERSION, "next_sequence": 1, "messages": {}}
            self._commit(state)
            return dict(state)
        finally:
            lock.release()

    def enqueue(self, message_id: str, payload, available_at=None) -> dict:
        _require_nonempty_str(message_id, "message_id")
        payload_bytes = _payload_canonical(payload)
        if len(payload_bytes) > self._limits.max_payload_bytes:
            raise SpoolError(
                CODE_INVALID_INPUT,
                "payload exceeds max_payload_bytes",
                {"size": len(payload_bytes), "max": self._limits.max_payload_bytes},
            )
        if available_at is None:
            avail = self._now()
        else:
            if not _is_finite_number(available_at):
                raise SpoolError(CODE_INVALID_INPUT, "available_at must be a finite number", {})
            avail = float(available_at)

        def fn(state: dict):
            if message_id in state["messages"]:
                existing = state["messages"][message_id]
                same_payload = _payload_canonical(existing["payload"]) == payload_bytes
                same_avail = existing["available_at"] == avail
                if same_payload and same_avail:
                    return _message_public(existing)
                raise SpoolError(
                    CODE_IDEMPOTENCY_CONFLICT,
                    "message_id reused with different payload or available_at",
                    {"message_id": message_id},
                )
            if len(state["messages"]) >= self._limits.max_messages:
                raise SpoolError(
                    CODE_CAPACITY_EXCEEDED,
                    "max_messages exceeded",
                    {"max": self._limits.max_messages},
                )
            seq = state["next_sequence"]
            state["next_sequence"] = seq + 1
            state["messages"][message_id] = {
                "message_id": message_id,
                "payload": _canonical_obj(payload),
                "status": "pending",
                "available_at": avail,
                "sequence": seq,
                "attempts": 0,
                "last_error": None,
                "worker_id": None,
                "lease_token": None,
                "expires_at": None,
            }
            return _message_public(state["messages"][message_id])

        return self._mutate(fn)

    def _find_claimable(self, state: dict, now: float) -> Optional[str]:
        candidates = [
            (m["available_at"], m["sequence"], mid)
            for mid, m in state["messages"].items()
            if m["status"] == "pending" and m["available_at"] <= now
        ]
        if not candidates:
            return None
        candidates.sort()
        return candidates[0][2]

    def claim(self, worker_id: str) -> Optional[dict]:
        _require_nonempty_str(worker_id, "worker_id")
        now = self._now()

        claimed = {}

        def fn(state: dict):
            mid = self._find_claimable(state, now)
            if mid is None:
                return None
            msg = state["messages"][mid]
            token = secrets.token_hex(16)
            msg["status"] = "leased"
            msg["attempts"] = msg["attempts"] + 1
            msg["worker_id"] = worker_id
            msg["lease_token"] = token
            msg["expires_at"] = now + self._limits.lease_seconds
            claimed["msg"] = _message_public(msg)
            claimed["token"] = token
            return claimed["msg"]

        result = self._mutate(fn)
        if result is None:
            return None
        out = dict(result)
        out["lease_token"] = claimed["token"]
        return out

    def _find_leased(self, state: dict, message_id: str):
        if message_id not in state["messages"]:
            return None
        msg = state["messages"][message_id]
        if msg["status"] != "leased":
            return None
        return msg

    def ack(self, message_id: str, lease_token: str) -> dict:
        _require_nonempty_str(message_id, "message_id")
        _require_nonempty_str(lease_token, "lease_token")

        def fn(state: dict):
            msg = self._find_leased(state, message_id)
            if msg is None:
                # Determine reason without revealing token.
                if message_id not in state["messages"]:
                    raise SpoolError(CODE_NOT_FOUND, "message not found", {"message_id": message_id})
                raise SpoolError(CODE_UNAUTHORIZED, "not authorized", {})
            if not secrets.compare_digest(msg["lease_token"], lease_token):
                raise SpoolError(CODE_UNAUTHORIZED, "not authorized", {})
            msg["status"] = "acked"
            msg["worker_id"] = None
            msg["lease_token"] = None
            msg["expires_at"] = None
            return _message_public(msg)

        return self._mutate(fn)

    def fail(self, message_id: str, lease_token: str, error: str) -> dict:
        _require_nonempty_str(message_id, "message_id")
        _require_nonempty_str(lease_token, "lease_token")
        if not _is_nonempty_str(error):
            raise SpoolError(CODE_INVALID_INPUT, "error must be a non-empty string", {})

        def fn(state: dict):
            msg = self._find_leased(state, message_id)
            if msg is None:
                if message_id not in state["messages"]:
                    raise SpoolError(CODE_NOT_FOUND, "message not found", {"message_id": message_id})
                raise SpoolError(CODE_UNAUTHORIZED, "not authorized", {})
            if not secrets.compare_digest(msg["lease_token"], lease_token):
                raise SpoolError(CODE_UNAUTHORIZED, "not authorized", {})
            msg["last_error"] = error
            msg["worker_id"] = None
            msg["lease_token"] = None
            msg["expires_at"] = None
            if msg["attempts"] >= self._limits.max_attempts:
                msg["status"] = "dead"
            else:
                msg["status"] = "pending"
                msg["available_at"] = self._now() + self._limits.retry_delay
            return _message_public(msg)

        return self._mutate(fn)

    def recover(self) -> dict:
        now = self._now()

        def fn(state: dict):
            recovered = 0
            for mid, msg in state["messages"].items():
                if msg["status"] == "leased" and now >= msg["expires_at"]:
                    msg["worker_id"] = None
                    msg["lease_token"] = None
                    msg["expires_at"] = None
                    if msg["attempts"] >= self._limits.max_attempts:
                        msg["status"] = "dead"
                    else:
                        msg["status"] = "pending"
                        msg["available_at"] = now
                    recovered += 1
            return {"recovered": recovered}

        return self._mutate(fn)

    def get(self, message_id: str) -> dict:
        _require_nonempty_str(message_id, "message_id")

        def fn(state: dict):
            if message_id not in state["messages"]:
                raise SpoolError(CODE_NOT_FOUND, "message not found", {"message_id": message_id})
            return _message_public(state["messages"][message_id])

        return self._read_locked(fn)

    def list_messages(self, status=None) -> list:
        if status is not None:
            if status not in VALID_STATUSES:
                raise SpoolError(CODE_INVALID_INPUT, "invalid status filter", {"status": status})

        def fn(state: dict):
            msgs = [m for m in state["messages"].values()]
            if status is not None:
                msgs = [m for m in msgs if m["status"] == status]
            msgs.sort(key=lambda m: (m["available_at"], m["sequence"], m["message_id"]))
            return [_message_public(m) for m in msgs]

        return self._read_locked(fn)


# ---------------------------------------------------------------------------
# Lock handle + duplicate key detection
# ---------------------------------------------------------------------------
class _LockHandle:
    def __init__(self, path: str):
        self._path = path

    def release(self) -> None:
        # A pre-existing lock is never deleted merely because it is old.
        # We only remove the lock we created ourselves (via O_EXCL).
        try:
            os.remove(self._path)
        except FileNotFoundError:
            pass
        except OSError:
            pass


def _has_duplicate_keys(text: str) -> bool:
    """Detect duplicate object keys in a JSON string (json.loads keeps last)."""
    decoder = json.JSONDecoder()
    idx = 0
    n = len(text)
    while idx < n:
        ch = text[idx]
        if ch in " \t\r\n":
            idx += 1
            continue
        if ch in "{[":
            try:
                _, end = decoder.raw_decode(text[idx:])
            except json.JSONDecodeError:
                return False
            obj_text = text[idx : idx + end]
            if _object_has_dup_keys(obj_text):
                return True
            idx += end
        else:
            idx += 1
    return False


def _object_has_dup_keys(obj_text: str) -> bool:
    decoder = json.JSONDecoder()
    try:
        obj = decoder.decode(obj_text)
    except json.JSONDecodeError:
        return False

    def walk(node, path):
        if isinstance(node, dict):
            seen = set()
            for k, v in node.items():
                if k in seen:
                    return True
                seen.add(k)
                if walk(v, path):
                    return True
        elif isinstance(node, list):
            for item in node:
                if walk(item, path):
                    return True
        return False

    return walk(obj, "")


__all__ = ["Limits", "Spool", "SpoolError"]

