import sys, tempfile, os, multiprocessing
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from src.delivery_spool import Spool, Limits

root = tempfile.mkdtemp()

def setup():
    s = Spool(root, clock=lambda: 0.0, limits=Limits(), lock_timeout=5.0, failpoint=None)
    s.initialize()
    for i in range(10):
        s.enqueue(f"m{i}", i)

def claimer(q):
    try:
        s = Spool(root, clock=lambda: 0.0, limits=Limits(), lock_timeout=5.0, failpoint=None)
        claimed = []
        while True:
            c = s.claim("w")
            if c is None:
                break
            claimed.append(c["message_id"])
        q.put(claimed)
    except Exception as e:
        q.put(("ERR", str(e)))

if __name__ == "__main__":
    multiprocessing.freeze_support()
    q = multiprocessing.Queue()
    setup()
    procs = [multiprocessing.Process(target=claimer, args=(q,)) for _ in range(4)]
    for p in procs: p.start()
    for p in procs: p.join()
    all_claimed = []
    for _ in procs:
        all_claimed.extend(q.get())
    print("total_claimed", len(all_claimed))
    print("unique_claimed", len(set(all_claimed)))
    s = Spool(root, clock=lambda: 0.0, limits=Limits(), lock_timeout=5.0, failpoint=None)
    leased = [m for m in s.list_messages() if m["status"] == "leased"]
    print("still_leased", len(leased))

