def _has_duplicate_keys(text: str) -> bool:
    """Detect duplicate object keys in a JSON string (json.loads keeps last)."""
    decoder = json.JSONDecoder()
    idx = 0
    n = len(text)
    while idx < n:
        ch = text[idx]
        if ch in " \t\r\n":
            idx += 1
            continue
        if ch in "{[":
            try:
                _, end = decoder.raw_decode(text[idx:])
            except json.JSONDecodeError:
                return False
            obj_text = text[idx : idx + end]
            if _object_has_dup_keys(obj_text):
                return True
            idx += end
        else:
            idx += 1
    return False


def _object_has_dup_keys(obj_text: str) -> bool:
    decoder = json.JSONDecoder()
    try:
        obj = decoder.decode(obj_text)
    except json.JSONDecodeError:
        return False

    def walk(node, path):
        if isinstance(node, dict):
            seen = set()
            for k, v in node.items():
                if k in seen:
                    return True
                seen.add(k)
                if walk(v, path):
                    return True
        elif isinstance(node, list):
            for item in node:
                if walk(item, path):
                    return True
        return False

    return walk(obj, "")


